// R7RS Benchmark: sumfp (Typed version)
// Sum of floats from 0.0 to 100000.0, repeated 1 time
// Adapted from r7rs-benchmarks/src/sumfp.scm (scaled down for Lambda JIT)

fn run(n: float) float {
    var work_n: float = n

    var s: float = 0.0
    while (work_n >= 0.0) {
        s = s + work_n
        work_n = work_n - 1.0
    }
    return s
}

fn benchmark() float {
    var result = run(100000.0)
    return result
}

pn main() {
    let t0 = clock()
    var total: float = 0.0
    var i: int = 0
    while (i < 10000) { total = total + benchmark(); i = i + 1 }
    let elapsed = (clock() - t0) * 1000.0
    if (abs(total - 5000050000.0 * 10000.0) < 1.0) { print("sumfp: PASS\n") }
    else { print("sumfp: FAIL\n") }
    print("__TIMING__:" ++ elapsed ++ "\n")
}

