/* Native C2MIR port of r7rs/sumfp2.ls. */
extern int printf(const char *, ...);
#include "/Users/henryluo/Projects/lambda/test/benchmark/c2mir/bench_kernel_timer.h"

static double run_sumfp(double n) {
    double sum = 0.0;
    while (n >= 0.0) {
        sum += n;
        n -= 1.0;
    }
    return sum;
}

int main(void) {
    BENCH_KERNEL_BEGIN();
    double total = 0.0;
    long i;
    for (i = 0; i < 10000; i++) total += run_sumfp(100000.0);
    BENCH_KERNEL_END();
    double diff = total - 5000050000.0 * 10000.0;
    if (diff < 0.0) diff = -diff;
    printf(diff < 1.0 ? "sumfp: PASS\n" : "sumfp: FAIL\n");
    BENCH_KERNEL_REPORT();
    return diff >= 1.0;
}
